using System.Collections.ObjectModel;using System.Windows;using System.Windows.Input;using MFCYouthAreaManagementSystem.Models;using MFCYouthAreaManagementSystem.Repositories;using MFCYouthAreaManagementSystem.ViewModels.Base;using MFCYouthAreaManagementSystem.Views.Dialogs;
namespace MFCYouthAreaManagementSystem.ViewModels;
public sealed class ServicesViewModel:ObservableObject{private readonly ServiceRepository _repo=new();public ObservableCollection<Service> Services{get;}=new();private string _search="";public string SearchText{get=>_search;set{if(SetProperty(ref _search,value))Load();}}private Service? _selected;public Service? SelectedService{get=>_selected;set{if(SetProperty(ref _selected,value))CommandManager.InvalidateRequerySuggested();}}public ICommand ViewMembersCommand{get;}public ICommand RefreshCommand{get;}public ServicesViewModel(){ViewMembersCommand=new RelayCommand(ViewMembers,()=>SelectedService!=null);RefreshCommand=new RelayCommand(Load);Load();}public void Load(){try{Services.Clear();foreach(var s in _repo.GetAll(SearchText??""))Services.Add(s);}catch(Exception ex){MessageBox.Show(Application.Current?.MainWindow,ex.Message,"Unable to load services",MessageBoxButton.OK,MessageBoxImage.Warning);}}private void ViewMembers(){if(SelectedService!=null)new ServiceMembersWindow(SelectedService.ServiceID,SelectedService.ServiceName){Owner=Application.Current?.MainWindow}.ShowDialog();}}
